import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.InjectMocks;
import org.mockito.junit.MockitoJUnitRunner;
import static org.junit.Assert.*;
import io.netty.buffer.Unpooled;
import io.netty.channel.Channel;
import org.traccar.model.Position;
import org.traccar.Protocol;

import java.nio.charset.StandardCharsets;
import java.util.TimeZone;

@RunWith(MockitoJUnitRunner.class)
public class Gt06ProtocolDecoderTest {

    @InjectMocks
    private Gt06ProtocolDecoder gt06ProtocolDecoder;

    private Protocol protocol = new Protocol("gt06");

    @Test
    public void decodeGpsHasLengthTest() {
        Position position = new Position();
        byte[] rawData = {0x10, 0x20, 0x30, 0x40};
        boolean isDecoded = Gt06ProtocolDecoder.decodeGps(position, Unpooled.wrappedBuffer(rawData), true, TimeZone.getDefault());
        assertTrue(isDecoded);
    }

    @Test
    public void decodeGpsWithoutLengthTest() {
        Position position = new Position();
        byte[] rawData = {0x10, 0x20, 0x30, 0x40};
        boolean isDecoded = Gt06ProtocolDecoder.decodeGps(position, Unpooled.wrappedBuffer(rawData), false, TimeZone.getDefault());
        assertTrue(isDecoded);
    }

    @Test
    public void decodeGpsWithAdditionalParamsTest() {
        Position position = new Position();
        byte[] rawData = {0x10, 0x20, 0x30, 0x40};
        boolean isDecoded = Gt06ProtocolDecoder.decodeGps(position, Unpooled.wrappedBuffer(rawData), true, true, true, TimeZone.getDefault());
        assertTrue(isDecoded);
    }


    @Test(expected = Exception.class)
    public void decodeNullChannelTest() throws Exception {
    	gt06ProtocolDecoder = new Gt06ProtocolDecoder(protocol);
        byte[] rawData = {0x10, 0x20, 0x30, 0x40};
        Object decoded = gt06ProtocolDecoder.decode(null, null, rawData);
        assertNull(decoded);
    }

    @Test(expected = Exception.class)
    public void decodeEmptyMessageTest() throws Exception {
    	gt06ProtocolDecoder = new Gt06ProtocolDecoder(protocol);
        Channel channel = mock(Channel.class);
        Object decoded = gt06ProtocolDecoder.decode(channel, null, "");
        assertNull(decoded);
    }

    @Test(expected = Exception.class)
    public void decodeInvalidMessageTest() throws Exception {
    	gt06ProtocolDecoder = new Gt06ProtocolDecoder(protocol);
        Channel channel = mock(Channel.class);
        byte[] rawData = {0x10, 0x20, 0x30, 0x40};
        gt06ProtocolDecoder.decode(channel, null, Unpooled.wrappedBuffer(rawData));
    }
}
